-- PostgreSQL script made by Puddle from the project's DBML

CREATE SCHEMA IF NOT EXISTS "billing";

CREATE TYPE "billing"."plan" AS ENUM ('free', 'pro');

CREATE TABLE "billing"."accounts" (
  "id" uuid PRIMARY KEY,
  "plan" "billing"."plan" DEFAULT 'free' NOT NULL,
  "active" boolean DEFAULT true,
  "settings" jsonb,
  "location" geometry,
  "opened" date
);

CREATE TABLE "authors" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(80) NOT NULL,
  "account_id" uuid
);

CREATE TABLE "books" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" text NOT NULL,
  "price" numeric(8,2) CHECK (price > 0),
  "added" timestamptz DEFAULT (now())
);

CREATE TABLE "books_authors" (
  "books_id" bigint NOT NULL,
  "authors_id" bigint NOT NULL,
  PRIMARY KEY ("books_id", "authors_id")
);

ALTER TABLE "authors" ADD FOREIGN KEY ("account_id") REFERENCES "billing"."accounts" ("id") ON DELETE SET NULL ON UPDATE RESTRICT;
ALTER TABLE "books_authors" ADD FOREIGN KEY ("books_id") REFERENCES "books" ("id");
ALTER TABLE "books_authors" ADD FOREIGN KEY ("authors_id") REFERENCES "authors" ("id");

COMMENT ON TABLE "billing"."accounts" IS 'One per paying customer';
COMMENT ON COLUMN "billing"."accounts"."opened" IS 'When the account was opened';

